"use strict";function query(n){console.log($("#FromDate").val());$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{FullName:$("#FullName").val(),PositionId:$("#PositionId").val(),Status:$("#Status").val(),FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteApplicant(n){confirm("Are you sure you want to delete?",function(){$.post(_global.root+"applicants/Delete",{id:n},function(n){n.IsSuccessful?query(!1):alert(n.Message)}).error(function(){alert(_messages.errorTryAgain)})})}$(document).ready(function(){$("#FullName").keyup(function(n){n.keyCode===13&&query(!1)});$("#submit").on("click",function(){query(!1)});var n=getParam("query");n!=null&&$("#keyword").val(n);query(!0)});